//@category SP11.Camera
import ghidra.app.script.GhidraScript; import ghidra.app.decompiler.*; import ghidra.program.model.listing.*; import ghidra.program.model.symbol.*; import ghidra.program.model.data.*; import java.io.*; import java.util.*;
public class ExtractIFEDSPMethods extends GhidraScript {
 public void run() throws Exception {String[] a=getScriptArgs(); PrintWriter p=new PrintWriter(new FileOutputStream(a[0])); Listing l=currentProgram.getListing(); ReferenceManager rm=currentProgram.getReferenceManager(); FunctionManager fm=currentProgram.getFunctionManager(); LinkedHashSet<Function> roots=new LinkedHashSet<>(); DataIterator it=l.getDefinedData(true); while(it.hasNext()){Data d=it.next(); Object v=d.getValue(); if(!(v instanceof String))continue; String s=((String)v); if(!s.contains("CamX::IFEDSPInterface::")&&!s.contains("HVX_EVENT_"))continue; p.println("STRING @"+d.getAddress()+" = "+s); ReferenceIterator ri=rm.getReferencesTo(d.getAddress()); while(ri.hasNext()){Reference rr=ri.next(); Function f=fm.getFunctionContaining(rr.getFromAddress()); p.println(" XREF "+rr.getFromAddress()+" function="+(f==null?"":f.getName())+" entry="+(f==null?"":f.getEntryPoint())); if(f!=null)roots.add(f);}} DecompInterface di=new DecompInterface(); di.openProgram(currentProgram); p.println("\n=== ROOTS ==="); for(Function f:roots){p.println(f.getName()+" @"+f.getEntryPoint()); p.println("\n//// "+f.getName()+" @"+f.getEntryPoint()+" ////"); DecompileResults dr=di.decompileFunction(f,180,monitor); if(dr!=null&&dr.decompileCompleted()&&dr.getDecompiledFunction()!=null)p.println(dr.getDecompiledFunction().getC());} di.dispose(); p.close(); }
}
